<?php

declare(strict_types=1);

namespace Koravik\Districts\Gather;

use Koravik\Platform\Database\Database;
use Koravik\Platform\Security\Security;
use RuntimeException;

final class GatherController
{
    public function __construct(private readonly Database $database) {}

    public function handle(string $method,string $path): bool
    {
        if((new GatherOperationsController($this->database))->handle($method,$path))return true;
        if($method==='GET'&&$path==='/gather'){$this->index();return true;}
        if($method==='GET'&&$path==='/gather/calendar'){$this->calendar();return true;}
        if($method==='POST'&&$path==='/gather/events'){$this->createEvent();return true;}
        if($method==='GET'&&preg_match('#^/gather/events/([a-f0-9-]{36})$#',$path,$m)){$this->event($m[1]);return true;}
        if($method==='POST'&&preg_match('#^/gather/events/([a-f0-9-]{36})/guest-rsvp$#',$path,$m)){$this->guestRsvp($m[1]);return true;}
        if($method==='POST'&&$path==='/gather/rsvp/lookup'){$this->lookup();return true;}
        if($method==='GET'&&preg_match('#^/gather/rsvp/manage/([A-Za-z0-9_-]+)$#',$path,$m)){$this->manage($m[1]);return true;}
        if($method==='POST'&&preg_match('#^/gather/rsvp/manage/([A-Za-z0-9_-]+)$#',$path,$m)){$this->updateManaged($m[1]);return true;}
        if($method==='POST'&&preg_match('#^/gather/rsvp/manage/([A-Za-z0-9_-]+)/cancel$#',$path,$m)){$this->cancelManaged($m[1]);return true;}
        if($method==='POST'&&preg_match('#^/gather/rsvp/manage/([A-Za-z0-9_-]+)/slots/([a-f0-9-]{36})/claim$#',$path,$m)){$this->claimManaged($m[1],$m[2]);return true;}
        if($method==='POST'&&preg_match('#^/gather/rsvp/manage/([A-Za-z0-9_-]+)/commitments/([a-f0-9-]{36})/cancel$#',$path,$m)){$this->cancelCommitment($m[1],$m[2]);return true;}
        if($method==='POST'&&preg_match('#^/gather/events/([a-f0-9-]{36})/slots$#',$path,$m)){$this->slot($m[1]);return true;}
        if($method==='POST'&&preg_match('#^/gather/slots/([a-f0-9-]{36})/claim$#',$path,$m)){$this->claim($m[1]);return true;}
        return false;
    }

    private function index(): void
    {
        $a=Security::requireAccount();$events=(new GatherService($this->database))->dashboard((string)$a['id']);$cards='';foreach($events as $e){$cards.='<article class="surface"><p class="eyebrow">'.self::e(ucfirst((string)$e['status'])).'</p><h2>'.self::e((string)$e['title']).'</h2><p>'.self::e((string)$e['starts_at']).' UTC</p><p>'.self::e((string)($e['venue']??'')).'</p><p><a class="button" href="/gather/events/'.self::e((string)$e['id']).'/command">Command center</a> <a class="button secondary" href="/gather/events/'.self::e((string)$e['id']).'">Event view</a></p></article>';}
        $presence='<section class="surface gather-host-operating-system gather-broad-presence-pass"><h2>Gather Host Operating System</h2><p>Gather now presents the full event lifecycle in one place: public preview, RSVP and guest management, signup board, waitlists, agenda, day-of check-in, communications, closeout, aftercare, and Source Inbox handoff.</p><p class="local-actions"><a href="/gather/calendar">Calendar/list view</a><a href="/source-review?owner=gather">Gather decisions</a><a href="/beacon">Beacon sharing</a></p></section>';
        $body='<section class="page-heading"><div><p class="eyebrow">Gather</p><h1>Plan the whole event in one place.</h1><p>Guest registration, RSVPs, shifts, potluck items, waitlists, attendance, and communications orbit the event.</p></div><a class="button secondary" href="/gather/calendar">Calendar/list view</a></section>'.$presence.'<section class="surface"><h2>Create an event</h2><form method="post" action="/gather/events" class="form-grid"><input type="hidden" name="csrf" value="'.self::e(Security::csrfToken()).'"><label>Title<input name="title" maxlength="180" required></label><label>Starts<input name="starts_at" type="datetime-local" required></label><label>Ends<input name="ends_at" type="datetime-local"></label><label>Venue<input name="venue"></label><label>Event capacity<input name="capacity" type="number" min="1"></label><label>Visibility<select name="visibility"><option value="unlisted">Anyone with the link</option><option value="public">Public</option><option value="restricted">Restricted</option></select></label><label>Event accent color<input name="event_accent_color" type="color" value="#D4A53A"></label><label>Event header style<select name="event_header_style"><option value="classic">Classic parchment</option><option value="forest">Forest</option><option value="gold">Warm gold</option><option value="navy">Deep navy</option><option value="custom">Use my accent strongly</option></select></label><label><input type="checkbox" name="guest_registration_enabled" checked> Allow registration without a Koravik account</label><label><input type="checkbox" name="additional_guests_enabled"> Allow additional guests</label><label>Maximum additional guests per RSVP<input name="max_additional_guests" type="number" min="0" value="0"></label><label><input type="checkbox" name="waitlist_enabled" checked> Enable event waitlist</label><label><input type="checkbox" name="automatic_waitlist_promotion"> Allow automatic promotion</label><label class="full">Description<textarea name="description"></textarea></label><button class="button" type="submit">Create event</button></form></section><section><h2>Your events</h2><div class="grid">'.($cards?:'<article class="empty-state"><h3>No events yet.</h3><p>Create one and Gather will quietly provision its Beacon sharing tools.</p></article>').'</div></section>';
        echo $this->page('Gather',$body);
    }

    private function calendar(): void
    {
        $a=Security::requireAccount();$events=(new GatherService($this->database))->dashboard((string)$a['id']);$status=(string)($_GET['status']??'');$items='';foreach($events as $e){if($status!==''&&$status!==(string)$e['status'])continue;$items.='<article class="gather-calendar-item"><time>'.self::e(substr((string)$e['starts_at'],0,10)).'</time><div><p class="eyebrow">'.self::e(ucfirst((string)$e['status'])).' · '.self::e((string)$e['visibility']).'</p><h2>'.self::e((string)$e['title']).'</h2><p>'.self::e((string)($e['venue']??'Location pending')).'</p><a href="/gather/events/'.self::e((string)$e['id']).'">Open event detail</a></div></article>';}
        $body='<section class="page-heading gather-calendar-list"><div><p class="eyebrow">Gather calendar/list view</p><h1>Shared experiences by date.</h1><p>Use the list view for scanning, filtering, keyboard navigation, and accessible alternatives to calendar grids.</p></div><a href="/gather">Create event</a></section><form class="surface" method="get" action="/gather/calendar"><label>Status filter<select name="status"><option value="">All statuses</option><option value="draft">Draft</option><option value="published">Published</option><option value="cancelled">Cancelled</option><option value="completed">Completed</option></select></label><button class="button secondary">Filter</button></form><section class="gather-calendar-list">'.($items?:'<article class="empty-state"><h2>No matching events.</h2></article>').'</section>';
        echo $this->page('Gather calendar',$body);
    }

    private function event(string $id): void
    {
        $service=new GatherService($this->database);$account=Security::account();$e=$account?$service->event((string)$account['id'],$id):$service->publicEvent($id);if(!$e){http_response_code(404);echo $this->page('Event not found','<section class="empty-state"><h1>Event not found.</h1></section>');return;}
        $owner=$account&&((string)$account['id']===(string)$e['account_id']);$r='';if($owner)foreach($e['rsvps'] as $x){$r.='<li><strong>'.self::e((string)($x['guest_name']?:'Koravik member')).'</strong> · '.self::e(ucfirst((string)$x['response'])).' · '.(int)$x['party_size'].' person(s)</li>';}
        $slotGroups=[];foreach($e['slots'] as $s){$slotGroups[(string)($s['category_label']??ucfirst((string)$s['slot_type']))][]=$s;}$slots='';foreach($slotGroups as $label=>$items){$cards='';foreach($items as $s){$claims='';foreach($s['commitments'] as $c){$claims.='<li>'.self::e((string)($c['participant_name']?:'Participant')).' · '.(int)$c['quantity'].' · '.self::e((string)$c['status']).'</li>';}$remaining=max(0,(int)$s['quantity_needed']-(int)$s['quantity_claimed']);$claimForm='<form method="post" action="/gather/slots/'.self::e((string)$s['id']).'/claim"><input type="hidden" name="csrf" value="'.self::e(Security::csrfToken()).'"><label>Name<input name="name" required></label><label>Email<input name="email" type="email" required></label><label>Quantity<input name="quantity" type="number" min="1"'.($s['max_quantity_per_commitment']?' max="'.(int)$s['max_quantity_per_commitment'].'"':'').' value="1"></label><button class="button secondary" type="submit">'.($remaining>0?'Sign up':'Join waitlist').'</button></form>';$cards.='<article class="surface gather-signup-card category-'.self::e((string)($s['category_key']?:$s['slot_type'])).'"><p class="eyebrow">'.self::e((string)($s['category_label']??ucfirst((string)$s['slot_type']))).' · '.self::e(ucfirst((string)$s['slot_type'])).'</p><h3>'.self::e((string)$s['title']).'</h3>'.($s['description']?'<p>'.self::e((string)$s['description']).'</p>':'').'<p><strong>'.$remaining.'</strong> of '.(int)$s['quantity_needed'].' still needed'.((int)$s['waitlist_enabled']?' · waitlist available':'').'</p>'.($s['starts_at']?'<p class="meta">'.self::e((string)$s['starts_at']).($s['ends_at']?'–'.self::e((string)$s['ends_at']):'').'</p>':'').'<ul>'.($claims?:'<li>No one has claimed this yet.</li>').'</ul>'.$claimForm.'</article>';}$slots.='<section class="gather-signup-category"><div class="section-heading"><h2>'.self::e($label).'</h2><span>'.count($items).' need'.(count($items)===1?'':'s').'</span></div><div class="grid">'.$cards.'</div></section>';}
        $guestForm=(int)$e['guest_registration_enabled']?'<article class="surface"><h2>RSVP</h2><form method="post" action="/gather/events/'.self::e($id).'/guest-rsvp"><input type="hidden" name="csrf" value="'.self::e(Security::csrfToken()).'"><label>Name<input name="guest_name" required></label><label>Email<input name="guest_email" type="email" required></label><label>Response<select name="response"><option value="yes">Yes</option><option value="maybe">Maybe</option><option value="no">No</option></select></label>'.((int)$e['additional_guests_enabled']?'<label>Additional guests<input name="additional_guests" type="number" min="0" max="'.(int)$e['max_additional_guests'].'" value="0"></label>':'').'<label>Note<input name="note"></label><button class="button" type="submit">Save RSVP</button></form><hr><form method="post" action="/gather/rsvp/lookup"><input type="hidden" name="csrf" value="'.self::e(Security::csrfToken()).'"><label>Find my RSVP by email<input name="email" type="email" required></label><button class="button secondary" type="submit">Email my management link</button></form></article>':'';
        $ownerTools=$owner?'<article class="surface gather-signup-builder"><h2>Organizer tools</h2><p><a class="button" href="/gather/events/'.self::e($id).'/command">Open command center</a></p><h3>Add food, shifts, equipment, supplies, and every other need</h3><form method="post" action="/gather/events/'.self::e($id).'/slots"><input type="hidden" name="csrf" value="'.self::e(Security::csrfToken()).'"><label>Category<select name="category_key"><option value="food">Food and potluck</option><option value="shift">Volunteer shifts</option><option value="equipment">Equipment and gear</option><option value="supplies">Supplies and materials</option><option value="setup">Setup crew</option><option value="cleanup">Cleanup crew</option><option value="transport">Transportation</option><option value="childcare">Childcare and care roles</option><option value="accessibility">Accessibility support</option><option value="other">Other needs</option></select></label><label>Type<select name="type"><option value="potluck">Food / potluck item</option><option value="shift">Timed shift</option><option value="item">Equipment or supply</option><option value="task">Task or role</option></select></label><label>Title<input name="title" required placeholder="Soup, 6pm check-in, folding tables, extension cords"></label><label class="full">Description<textarea name="description" maxlength="500" placeholder="Dietary notes, equipment specs, arrival instructions, where to report"></textarea></label><label>Starts<input name="starts_at" type="datetime-local"></label><label>Ends<input name="ends_at" type="datetime-local"></label><label>Quantity needed<input name="quantity" type="number" min="1" value="1"></label><label>Max quantity per claim<input name="max_quantity_per_commitment" type="number" min="1"></label><label><input type="checkbox" name="multiple_signups_allowed" checked> Allow multiple signups</label><label>Maximum signups per participant<input name="max_signups_per_participant" type="number" min="1"></label><label><input type="checkbox" name="waitlist_enabled" checked> Enable signup waitlist</label><p class="form-note full">Attendance is required: if someone is not going, they cannot claim this need.</p><label><input type="checkbox" name="overlapping_shifts_allowed"> Allow overlapping shifts</label><button class="button" type="submit">Add signup need</button></form><h3>Responses</h3><ul>'.($r?:'<li>No responses yet.</li>').'</ul></article>':'';
        $detail='<section class="gather-event-detail-completion gather-public-event-preview surface"><h2>Gather Public Event Preview</h2><p>Public preview shows schedule, venue, registration availability, signup needs, and source ownership before a guest submits anything.</p><dl><div><dt>Schedule</dt><dd>'.self::e((string)$e['starts_at']).' UTC'.($e['ends_at']?' to '.self::e((string)$e['ends_at']).' UTC':'').'</dd></div><div><dt>RSVP state</dt><dd>'.count($e['rsvps']).' responses recorded by Gather</dd></div><div><dt>Signup status</dt><dd>'.count($e['slots']).' planning needs</dd></div><div><dt>Attendance</dt><dd>Check-in remains host-recorded Gather truth.</dd></div><div><dt>Follow-up</dt><dd><a href="/gather/events/'.self::e($id).'/closeout">Open closeout and follow-up drafts</a></dd></div><div><dt>Ownership</dt><dd>Beacon may share links and pages; Gather owns RSVP, signup, attendance, and follow-up.</dd></div></dl></section>';
        $lifecycle='<section class="surface gather-event-lifecycle-map"><h2>Gather Event Lifecycle Map</h2><p>Plan → publish → RSVP → signup → agenda → day-of → closeout → aftercare. Beacon can share the doorway; Gather keeps participant truth.</p><p class="local-actions"><a href="/gather/events/'.self::e($id).'/agenda">Agenda</a><a href="/gather/events/'.self::e($id).'/day-of">Day-of operations</a><a href="/gather/events/'.self::e($id).'/closeout">Closeout and aftercare</a></p></section>';
        $brandColor=preg_match('/^#[0-9a-fA-F]{6}$/',(string)($e['organization_brand_color']??''))?(string)$e['organization_brand_color']:'#6d5b4d';$eventAccent=preg_match('/^#[0-9a-fA-F]{6}$/',(string)($e['event_accent_color']??''))?(string)$e['event_accent_color']:$brandColor;$eventStyle=(string)($e['event_header_style']??'classic');$eventVars='style="--event-accent:'.self::e($eventAccent).'"';$orgName=(string)($e['organization_public_name']?:($e['organization_name']??''));$branding=$orgName!==''?'<section class="surface gather-organization-branding" style="--event-accent:'.self::e($brandColor).';border-top:6px solid '.self::e($brandColor).'"><p class="eyebrow">Hosted by</p><h2>'.self::e($orgName).'</h2>'.($e['organization_summary']?'<p>'.self::e((string)$e['organization_summary']).'</p>':'').($e['organization_contact_email']?'<p class="meta">Contact '.self::e((string)$e['organization_contact_email']).'</p>':'').'</section>':'';
        $body='<section class="page-heading gather-public-view-page gather-event-header header-style-'.self::e($eventStyle).'" '.$eventVars.'><div><p class="eyebrow">Gather public view page · '.self::e((string)$e['visibility']).'</p><h1>'.self::e((string)$e['title']).'</h1><p>'.self::e((string)$e['description']).'</p><p><strong>'.self::e((string)$e['starts_at']).' UTC</strong> · '.self::e((string)($e['venue']??'Location pending')).'</p></div>'.($owner?'<a href="/gather">All events</a>':'').'</section>'.$branding.$lifecycle.$detail.'<section class="grid">'.$guestForm.$ownerTools.'</section><section class="gather-better-than-signupgenius"><h2>Signups</h2><p>Food, shifts, equipment, supplies, setup, cleanup, transportation, childcare, accessibility support, and custom roles stay grouped, waitlist-aware, and connected to RSVP/event truth.</p>'.($slots?:'<article class="empty-state"><h3>No signup needs yet.</h3></article>').'</section>';echo $this->page((string)$e['title'],$body);
    }

    private function manage(string $token):void{$r=(new GatherWorkflowService($this->database))->manageByToken($token);if(!$r){http_response_code(404);echo $this->page('RSVP link unavailable','<section class="empty-state"><h1>That RSVP link is unavailable.</h1></section>');return;}$safeToken=self::e($token);$additional=max(0,(int)$r['party_size']-1);$slots='';foreach($r['slots'] as $slot){$max=$slot['max_quantity_per_commitment']?' max="'.(int)$slot['max_quantity_per_commitment'].'"':'';$action=$slot['commitment_id']?'<p class="participant-status"><strong>'.self::e(ucfirst((string)$slot['commitment_status'])).'</strong> · '.(int)$slot['commitment_quantity'].' committed'.($slot['commitment_waitlist_position']?' · waitlist position '.(int)$slot['commitment_waitlist_position']:'').'</p><form method="post" action="/gather/rsvp/manage/'.$safeToken.'/commitments/'.self::e((string)$slot['commitment_id']).'/cancel">'.$this->csrfField().'<button class="quiet-button">Release this commitment</button></form>':'<form method="post" action="/gather/rsvp/manage/'.$safeToken.'/slots/'.self::e((string)$slot['id']).'/claim">'.$this->csrfField().'<label>Quantity<input type="number" name="quantity" min="1"'.$max.' value="1"></label><button class="button secondary">Choose this signup</button></form>';$slots.='<article class="participant-slot category-'.self::e((string)($slot['category_key']?:$slot['slot_type'])).'"><p class="eyebrow">'.self::e((string)($slot['category_label']??ucfirst((string)$slot['slot_type']))).' · '.self::e(ucfirst((string)$slot['slot_type'])).'</p><h3>'.self::e((string)$slot['title']).'</h3>'.($slot['description']?'<p>'.self::e((string)$slot['description']).'</p>':'').'<p>'.(int)$slot['quantity_claimed'].' of '.(int)$slot['quantity_needed'].' claimed'.((int)$slot['waitlist_enabled']?' · waitlist available':'').((int)$slot['require_attending_rsvp']?' · RSVP yes required':'').'</p>'.$action.'</article>';}$checkin=$r['checkin']?'<section class="participant-checkin"><p class="eyebrow">Attendance</p><h2>Checked in</h2><p>'.(int)$r['checkin']['party_count'].' people · '.self::e((string)$r['checkin']['checked_in_at']).' UTC</p></section>':'<section class="participant-checkin"><p class="eyebrow">Day of event</p><h2>Check-in is handled by the host.</h2><p>Your RSVP remains your attendance intent until Gather records check-in.</p></section>';$follow=in_array((string)$r['lifecycle_status'],['completed','closed','archived'],true)?'<section class="participant-followup"><h2>After the event</h2><p>Reflection and Chronicle memory remain optional and are never created from attendance alone.</p><a href="/chronicle/new?context=gather_reflection&title=Event%20reflection&tags=gather,reflection">Start a private reflection</a></section>':'';$body='<section class="page-heading participant-event-heading"><div><p class="eyebrow">Your Gather participation</p><h1>'.self::e((string)$r['title']).'</h1><p>'.self::e((string)$r['starts_at']).' · '.self::e((string)$r['venue']).'</p></div><span class="status">'.self::e(ucfirst((string)$r['response'])).'</span></section><section class="participant-journey" aria-label="Participation journey"><span class="complete">1 · RSVP</span><span>2 · Signups</span><span>3 · Attend</span><span>4 · Follow up</span></section><section class="surface gather-participant-communication-preferences"><h2>Participant communication preferences</h2><p>Gather sends only event-management messages needed for RSVP, signup, waitlist, and day-of coordination. Marketing or unrelated messages are outside this event preference.</p></section><section class="surface"><h2>Manage RSVP</h2><form method="post" action="/gather/rsvp/manage/'.$safeToken.'">'.$this->csrfField().'<label>Response<select name="response"><option value="yes"'.($r['response']==='yes'?' selected':'').'>Yes</option><option value="maybe"'.($r['response']==='maybe'?' selected':'').'>Maybe</option><option value="no"'.($r['response']==='no'?' selected':'').'>No</option></select></label>'.((int)$r['additional_guests_enabled']?'<label>Additional guests<input name="additional_guests" type="number" min="0" max="'.(int)$r['max_additional_guests'].'" value="'.$additional.'"></label>':'').'<label>Note<input name="note" value="'.self::e((string)$r['note']).'"></label><button class="button" type="submit">Update RSVP</button></form></section><section><h2>Signup commitments</h2><div class="participant-slot-grid">'.($slots?:'<p class="empty-state">No signup needs are available.</p>').'</div></section>'.$checkin.$follow.'<section class="participant-cancel"><h2>Cannot attend?</h2><p>Cancelling releases active signups and may open space for someone waiting.</p><form method="post" action="/gather/rsvp/manage/'.$safeToken.'/cancel" onsubmit="return confirm(\'Cancel this RSVP and its active signups?\')">'.$this->csrfField().'<button class="quiet-button">Cancel RSVP</button></form></section>';echo $this->page('Manage participation',$body);}
    private function createEvent():void{$this->csrf();$a=Security::requireAccount();try{$id=(new GatherService($this->database))->createEvent((string)$a['id'],$_POST);$_SESSION['flash']='Event created with Beacon sharing tools.';$this->go('/gather/events/'.$id);}catch(RuntimeException $e){$_SESSION['flash']=$e->getMessage();$this->go('/gather');}}
    private function guestRsvp(string $id):void{$this->csrf();try{$token=(new GatherService($this->database))->registerGuest($id,$_POST);$_SESSION['flash']='Your RSVP was saved. A management-link delivery has been queued.';$this->go('/gather/rsvp/manage/'.$token);}catch(RuntimeException $e){$_SESSION['flash']=$e->getMessage();$this->go('/gather/events/'.$id);}}
    private function lookup():void{$this->csrf();(new GatherService($this->database))->requestManagementLinks((string)($_POST['email']??''));$_SESSION['flash']='If that email is associated with an RSVP, a management link has been queued for delivery.';$this->go('/gather');}
    private function updateManaged(string $token):void{$this->csrf();try{(new GatherService($this->database))->updateManagedRsvp($token,$_POST);$_SESSION['flash']='RSVP updated.';}catch(RuntimeException $e){$_SESSION['flash']=$e->getMessage();}$this->go('/gather/rsvp/manage/'.$token);}
    private function cancelManaged(string $token):void{$this->csrf();try{(new GatherWorkflowService($this->database))->cancelRsvp($token);$_SESSION['flash']='RSVP cancelled and active signups released.';}catch(RuntimeException $e){$_SESSION['flash']=$e->getMessage();$this->go('/gather/rsvp/manage/'.$token);}$this->go('/gather');}
    private function claimManaged(string $token,string $slot):void{$this->csrf();try{$r=(new GatherWorkflowService($this->database))->manageByToken($token);if(!$r)throw new RuntimeException('That management link is unavailable.');$status=(new GatherWorkflowService($this->database))->claimSlot($slot,(string)$r['id'],(int)($_POST['quantity']??1));$_SESSION['flash']=$status==='waitlist'?'You joined the signup waitlist.':'Signup commitment confirmed.';}catch(RuntimeException $e){$_SESSION['flash']=$e->getMessage();}$this->go('/gather/rsvp/manage/'.$token);}
    private function cancelCommitment(string $token,string $commitment):void{$this->csrf();try{(new GatherWorkflowService($this->database))->cancelCommitment($token,$commitment);$_SESSION['flash']='Signup commitment released.';}catch(RuntimeException $e){$_SESSION['flash']=$e->getMessage();}$this->go('/gather/rsvp/manage/'.$token);}
    private function slot(string $id):void{$this->csrf();$a=Security::requireAccount();try{(new GatherService($this->database))->addSlot((string)$a['id'],$id,(string)($_POST['type']??''),(string)($_POST['title']??''),(int)($_POST['quantity']??1),$_POST);$_SESSION['flash']='Planning signup added.';}catch(RuntimeException $e){$_SESSION['flash']=$e->getMessage();}$this->go('/gather/events/'.$id);}
    private function claim(string $slotId):void{$this->csrf();$a=Security::account();try{$status=(new GatherService($this->database))->claimSlot($slotId,['account_id'=>$a['id']??null,'name'=>$_POST['name']??($a['display_name']??null),'email'=>$_POST['email']??($a['email']??null)],(int)($_POST['quantity']??1));$_SESSION['flash']=$status==='waitlist'?'That signup is full; you joined its waitlist.':'Signup confirmed.';}catch(RuntimeException $e){$_SESSION['flash']=$e->getMessage();}$this->go('/gather');}
    private function csrf():void{if(!Security::verifyCsrf((string)($_POST['csrf']??'')))throw new RuntimeException('Your session token expired.');}
    private function go(string $to):never{header('Location: '.$to,true,303);exit;}
    private function csrfField():string{return '<input type="hidden" name="csrf" value="'.self::e(Security::csrfToken()).'">';}
    private function page(string $title,string $body):string{$flash='';if(isset($_SESSION['flash'])){$flash='<div class="notice">'.self::e((string)$_SESSION['flash']).'</div>';unset($_SESSION['flash']);}return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.self::e($title).' · Koravik</title><link rel="stylesheet" href="/assets/app.css"><link rel="stylesheet" href="/assets/journey.css"><link rel="stylesheet" href="/assets/gather.css"><link rel="stylesheet" href="/assets/gather-participant.css"></head><body><main id="main" class="page gather-broad-stroke-presence">'.$flash.$body.'</main><footer>Koravik · Gather</footer></body></html>';}
    private static function e(string $v):string{return htmlspecialchars($v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
}
